def re_arrange(arr, n):
    pos = []
    neg = []
    for i in range(n):
        if arr[i] >= 0:
            pos.append(arr[i])
        else:
            neg.append(arr[i])

    result = []
    pos_idx = 0
    neg_idx = 0
    while pos_idx < len(pos) and neg_idx < len(neg):
        result.append(neg[neg_idx])
        result.append(pos[pos_idx])
        pos_idx += 1
        neg_idx += 1

    if pos_idx < len(pos):
        result.extend(pos[pos_idx:])
    elif neg_idx < len(neg):
        result.extend(neg[neg_idx:])

    return result

def heap_sort(arr):
    n = len(arr)

    # Build a max heap
    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    # Extract elements from the heap one by one
    for i in range(n - 1, 0, -1):
        arr[0], arr[i] = arr[i], arr[0]
        heapify(arr, i, 0)

    return arr

def heapify(arr, n, i):
    largest = i
    left = 2 * i + 1
    right = 2 * i + 2

    if left < n and arr[left] > arr[largest]:
        largest = left

    if right < n and arr[right] > arr[largest]:
        largest = right

    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify(arr, n, largest)

