def permutation_coefficient(n, k):
    if k > n:
        return 0
    result = 1
    for i in range(n, n-k, -1):
        result *= i
    return result

def count_element_freq(nested_tuple):
    element_freq = {}
    for element in nested_tuple:
        if isinstance(element, tuple):
            for sub_element in count_element_freq(element):
                element_freq[sub_element] = element_freq.get(sub_element, 0) + 1
        else:
            element_freq[element] = element_freq.get(element, 0) + 1
    return element_freq

